<?phpnamespace app\common\model;/** * 订单商品模型 */class OrderGoods extends BaseModel{    // 定义表名    protected $name = 'order_goods';    protected $updateTime = false;    // 定义主键    protected $pk = 'order_goods_id';    // 追加字段    protected $append = [];    /**     * 订单商品列表     */    public function image()    {        return $this->belongsTo('addons\\upload\\model\\UploadFile', 'image_id', 'file_id');    }    /**     * 关联商品表     */    public function goods()    {        return $this->belongsTo('app\\common\\model\\Goods','goods_id');    }    /**     * 关联商品规格表     */    public function spec()    {        return $this->belongsTo('app\\common\\model\\GoodsSpec', 'spec_sku_id', 'spec_sku_id');    }}